"""Writes project/builder-data.js from tools/builder_content.py. Usage: python3 tools/build_builder_data.py project"""
import sys, os, json
sys.path.insert(0, os.path.dirname(__file__))
from builder_content import ITEMS
folder = sys.argv[1] if len(sys.argv) > 1 else "project"
data = {cid: [dict(mp=a, frame=b, answer=c, wrong=d) for a, b, c, d in items] for cid, items in ITEMS.items()}
open(os.path.join(folder, "builder-data.js"), "w", encoding="utf-8").write(
    "/* GENERATED by tools/build_builder_data.py from tools/builder_content.py - do not edit by hand. */\n"
    "const ASTRO_BUILDER = " + json.dumps(data, indent=1, ensure_ascii=False) + ";\n")
print("wrote builder-data.js for", len(data), "concepts,", sum(len(v) for v in data.values()), "items")
